def transform(grid):
    """Recolor complete monochrome divider rows/columns to color 2."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    h, w = len(grid), len(grid[0])
    rows = [r for r in range(h) if len(set(grid[r])) == 1]
    cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    for r in rows:
        color = grid[r][0]
        for c in range(w):
            out[r][c] = 2 if grid[r][c] == color else grid[r][c]
    for c in cols:
        color = grid[0][c]
        for r in range(h):
            out[r][c] = 2 if grid[r][c] == color else grid[r][c]
    return out

